type DesktopLocaleContextValue = { locale: DesktopLocale; t: (text: string, params?: Record<string, string | number>) => string };
const DesktopLocaleContext = React.createContext<DesktopLocaleContextValue>({ locale: 'en', t: (text) => translations[text]?.[2] ?? text });

function isLocale(value: string | null): value is DesktopLocale {
  return value !== null && localeOrder.includes(value as DesktopLocale);
}

export function DesktopLocaleProvider({ children }: React.PropsWithChildren) {
  const [locale, setLocale] = React.useState<DesktopLocale | null>(null);
  React.useEffect(() => {
    let live = true;
    let stored: string | null = null;
    try { stored = window.localStorage.getItem(STORAGE_KEYS.locale); } catch { /* storage may be disabled */ }
    if (isLocale(stored)) { setLocale(stored); }
    else {
      const api = (window as Window & { chronomancerDesktop?: { getDefaultLocale?: () => Promise<string> } }).chronomancerDesktop;
      void api?.getDefaultLocale?.().then((candidate) => {
        if (!live) return;
        const detected = isLocale(candidate) ? candidate : 'en';
        try { window.localStorage.setItem(STORAGE_KEYS.locale, detected); } catch { /* keep the session language in memory */ }
        setLocale(detected);
      }).catch(() => { if (live) setLocale('en'); });
      if (!api?.getDefaultLocale) setLocale('en');
    }
    const onStorage = (event: StorageEvent) => {
      if (event.key === STORAGE_KEYS.locale && isLocale(event.newValue)) setLocale(event.newValue);
    };
    window.addEventListener('storage', onStorage);
    return () => { live = false; window.removeEventListener('storage', onStorage); };
  }, []);
  React.useEffect(() => {
    if (!locale) return;
    document.documentElement.lang = locale;
    const api = (window as Window & { chronomancerDesktop?: { setLocale?: (value: string) => Promise<boolean> } }).chronomancerDesktop;
    void api?.setLocale?.(locale);
  }, [locale]);
  const value = React.useMemo<DesktopLocaleContextValue>(() => ({
    locale: locale ?? 'en',
    t: (text, params) => {
      const index = localeOrder.indexOf(locale ?? 'en');
      const websiteKey = websiteKeyByRussian.get(text as never);
      const websiteTranslation = websiteKey ? websiteMessages[locale ?? 'en'][websiteKey as keyof typeof en] : undefined;
      const template = translations[text]?.[index] ?? (typeof websiteTranslation === 'string' ? websiteTranslation : undefined) ?? translations[text]?.[2] ?? text;
      return template.replace(/\{(\w+)\}/g, (match, key: string) => key in (params ?? {}) ? String(params![key]) : match);
    },
  }), [locale]);
  if (!locale) return null;
  return <DesktopLocaleContext.Provider value={value}>{children}</DesktopLocaleContext.Provider>;
}

export function useDesktopLocale() { return React.useContext(DesktopLocaleContext); }
